import { flights, historicalWeather } from '@airways/database/schema';
import {
  sql,
  desc,
  isNotNull,
} from 'drizzle-orm';
import type {
  FilterConfig,
  HeroStats,
  DelayDistribution,
  DayOfWeekStats,
  HourlyStats,
  DailyStats,
  RouteStats,
  FlightNumberStats,
  AircraftStats,
  DelayRecord,
  DailyOtpStats,
  MonthlyStats,
