    direction: activeDirection as 'dep' | 'arr' | '' || undefined,
    dow: activeDow !== '' && !isNaN(dowNum) && dowNum >= 0 && dowNum <= 6 ? dowNum : undefined,
    season: activeSeason as 'summer' | 'winter' | 'spring' | 'autumn' | '' || undefined,
